def _is_synthetic() -> bool:
    p = Path("data/clean/panel.parquet")
    if p.exists():
        try:
            import pandas as pd
            return bool(pd.read_parquet(p, columns=["synthetic"])["synthetic"].any())
        except Exception:
            pass
    return True


def _latest_date() -> str:
    p = Path("data/clean/panel.parquet")
    if p.exists():
        try:
            import pandas as pd
            d = pd.read_parquet(p, columns=["date"])["date"].max()
            return str(d)[:10]
        except Exception:
            pass
    return "no data"


def _load(path: str):
    import pandas as pd
    p = Path(path)
    return pd.read_parquet(p) if p.exists() else None


def _nc(t):
    return next((c for c in ("net_inr", "net_pnl_inr") if c in t.columns), None)


def _gc(t):
    return next((c for c in ("gross_inr", "gross_pnl_inr") if c in t.columns), None)


def _cc_sum(t) -> float:
    if "cost_inr" in t.columns:
        return float(t["cost_inr"].sum())
    if "entry_cost_inr" in t.columns:
        return float((t["entry_cost_inr"] + t["exit_cost_inr"]).sum())
    return 0.0


def _inr(v) -> str:
    try:
        return "n/a" if v != v else f"\u20b9{v:,.0f}"
    except Exception:
        return "n/a"


def _has_real_curl() -> bool:
    """Return True if bhavcopy_request.curl has a real cURL command."""
    p = Path("docs/bhavcopy_request.curl")
    if not p.exists():
        return False
    text = p.read_text(encoding="utf-8", errors="ignore").strip()
    return len(text) > 60 and "curl" in text.lower() and "http" in text.lower()


def _run_cmd(args: list[str]) -> tuple[int, str, str]:
    """Run edge-ai as a Python module, CWD = project root."""
    project_root = str(Path(__file__).parent.parent.parent.parent)
    try:
        result = subprocess.run(
            [sys.executable, "-m", "edge_ai"] + args,
            capture_output=True, text=True, timeout=180,
            cwd=project_root,
        )
        return result.returncode, result.stdout, result.stderr
    except subprocess.TimeoutExpired:
        return 1, "", "Timeout: operation took too long (>3 min)"
    except Exception as exc:
        return 1, "", str(exc)


